import numpy as np, pandas as pd
from math import erf, exp, log, sqrt

def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def bs_price(S, K, r, sigma, T, kind="call", q=0.0):
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    if kind == "call":
        return S * exp(-q * T) * norm_cdf(d1) - K * exp(-r * T) * norm_cdf(d2)
    return K * exp(-r * T) * norm_cdf(-d2) - S * exp(-q * T) * norm_cdf(-d1)

def true_iv(K, T, S=100.0, r=0.05, q=0.01):
    m = log(K / (S * exp((r - q) * T))) / sqrt(T)       # moneyness per root year
    atm = 0.22 - 0.045 * exp(-T / 0.3)                   # term structure: rises with T
    return atm - 0.08 * m + 0.10 * m * m                 # skew and smile

def make_chain(seed=2320, S=100.0, r=0.05, q=0.01):
    rng = np.random.default_rng(seed)
    rows = []
    for T in [1 / 12, 2 / 12, 3 / 12, 6 / 12, 1.0]:
        for K in range(70, 131, 5):
            for kind in ("call", "put"):
                mid = bs_price(S, K, r, true_iv(K, T, S, r, q), T, kind, q)
                half = max(0.025, 0.03 * mid)
                noise = 0.2 * half * rng.standard_normal()
                bid = max(round(mid - half + noise, 2), 0.0)
                ask = round(mid + half + noise, 2)
                rows.append([T, K, kind, bid, ask, int(rng.integers(0, 5000)), 0.0])
    df = pd.DataFrame(rows, columns=["T", "strike", "type", "bid", "ask", "volume", "age_min"])
    bad = rng.choice(len(df), 9, replace=False)
    df.loc[bad[:3], "bid"] = 0.0                                          # zero bids
    df.loc[bad[3:5], "bid"] = df.loc[bad[3:5], "ask"] + 0.05              # crossed
    df.loc[bad[5:7], "age_min"] = 240.0                                   # stale
    df.loc[bad[7:], "ask"] = (df.loc[bad[7:], "ask"] * 1.6).round(2)      # wide
    return df
from math import pi, isnan
# ---- level 1 ----
def mid(df):
    m = (df["bid"] + df["ask"]) / 2
    return m.where(df["bid"] > 0)

def clean_quotes(df, max_age_min=30, max_rel_spread=0.5):
    m = (df["bid"] + df["ask"]) / 2
    keep = ((df["bid"] > 0) & (df["bid"] <= df["ask"])
            & (df["age_min"] <= max_age_min)
            & ((df["ask"] - df["bid"]) / m < max_rel_spread))
    return df[keep].reset_index(drop=True)

def drop_report(df, max_age_min=30, max_rel_spread=0.5):
    out = {"zero_bid": 0, "crossed": 0, "stale": 0, "wide": 0}
    for b, a, age in zip(df["bid"], df["ask"], df["age_min"]):
        if b <= 0:
            out["zero_bid"] += 1
        elif b > a:
            out["crossed"] += 1
        elif age > max_age_min:
            out["stale"] += 1
        elif (a - b) / ((a + b) / 2) >= max_rel_spread:
            out["wide"] += 1
    return out

def implied_forward(df_T, r, T):
    w = df_T.assign(mid=mid(df_T)).pivot(index="strike", columns="type", values="mid")
    if "call" not in w or "put" not in w:
        return float("nan")
    w = w.dropna(subset=["call", "put"])
    if len(w) < 3:
        return float("nan")
    return float(np.median(w.index + exp(r * T) * (w["call"] - w["put"])))

def implied_q(F, S, r, T):
    return r - log(F / S) / T

def otm_quotes(df_T, F):
    keep = (((df_T["type"] == "put") & (df_T["strike"] < F))
            | ((df_T["type"] == "call") & (df_T["strike"] >= F)))
    return df_T[keep].sort_values("strike").reset_index(drop=True)

# ---- level 2 ----
def crr_price(S, K, r, sigma, T, n, kind="call", american=False, q=0.0):
    dt = T / n
    u = exp(sigma * sqrt(dt))
    d = 1 / u
    p = (exp((r - q) * dt) - d) / (u - d)
    if not 0 <= p <= 1:
        raise ValueError("p outside [0, 1]: use more steps")
    disc = exp(-r * dt)
    sign = 1.0 if kind == "call" else -1.0
    j = np.arange(n + 1)
    v = np.maximum(sign * (S * u ** (2 * j - n) - K), 0.0)
    for i in range(n - 1, -1, -1):
        v = disc * (p * v[1:] + (1 - p) * v[:-1])
        if american:
            j = np.arange(i + 1)
            v = np.maximum(v, sign * (S * u ** (2 * j - i) - K))
    return float(v[0])

def mc_price(S, K, r, sigma, T, kind="call", n_paths=100_000, seed=0, antithetic=True, q=0.0):
    rng = np.random.default_rng(seed)
    m = n_paths // 2 if antithetic else n_paths
    if m < 2:
        raise ValueError("need at least two independent samples")
    z = rng.standard_normal(m)
    drift, vol = (r - q - sigma ** 2 / 2) * T, sigma * sqrt(T)
    sign = 1.0 if kind == "call" else -1.0
    def pay(zz):
        return exp(-r * T) * np.maximum(sign * (S * np.exp(drift + vol * zz) - K), 0.0)
    y = (pay(z) + pay(-z)) / 2 if antithetic else pay(z)
    return float(y.mean()), float(y.std(ddof=1) / sqrt(m))

def compare_grid(S, r, q, sigma, strikes, expiries, n_steps, n_paths, seed):
    rows = []
    for T in expiries:
        for K in strikes:
            mc, se = mc_price(S, K, r, sigma, T, "put", n_paths, seed, True, q)
            rows.append({"K": K, "T": T,
                         "bs": bs_price(S, K, r, sigma, T, "put", q),
                         "tree_eu": crr_price(S, K, r, sigma, T, n_steps, "put", False, q),
                         "tree_am_put": crr_price(S, K, r, sigma, T, n_steps, "put", True, q),
                         "mc": mc, "mc_se": se})
    return pd.DataFrame(rows, columns=["K", "T", "bs", "tree_eu", "tree_am_put", "mc", "mc_se"])

# ---- level 3 ----
def _vega(S, K, r, sigma, T, q=0.0):
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    return S * exp(-q * T) * sqrt(T) * exp(-d1 * d1 / 2) / sqrt(2 * pi)

def implied_vol(price, S, K, r, T, kind="call", q=0.0):
    if kind == "call":
        lower, upper = max(S * exp(-q * T) - K * exp(-r * T), 0.0), S * exp(-q * T)
    elif kind == "put":
        lower, upper = max(K * exp(-r * T) - S * exp(-q * T), 0.0), K * exp(-r * T)
    else:
        raise ValueError("kind must be 'call' or 'put'")
    if not lower < price < upper:
        raise ValueError("no volatility fits this price")
    lo, hi, sigma = 1e-4, 5.0, 0.2
    for _ in range(50):
        diff = bs_price(S, K, r, sigma, T, kind, q) - price
        if abs(diff) < 1e-12:
            return sigma
        if diff > 0:
            hi = sigma
        else:
            lo = sigma
        v = _vega(S, K, r, sigma, T, q)
        new = sigma - diff / v if v > 1e-12 else lo - 1.0
        if not lo < new < hi:
            new = (lo + hi) / 2
        if abs(new - sigma) < 1e-14:
            return new
        sigma = new
    return sigma

def smile(clean, T, S, r, q):
    df_T = clean[np.isclose(clean["T"], T)]
    F = S * exp((r - q) * T)
    otm = otm_quotes(df_T, F)
    rows = []
    for K, kind, b, a in zip(otm["strike"], otm["type"], otm["bid"], otm["ask"]):
        try:
            iv = implied_vol((b + a) / 2, S, K, r, T, kind, q)
        except ValueError:
            iv = float("nan")
        rows.append([K, log(K / F) / sqrt(T), iv])
    return pd.DataFrame(rows, columns=["strike", "m", "iv"])

def fit_smile(m, iv, weights=None):
    m, iv = np.asarray(m, float), np.asarray(iv, float)
    w = np.ones_like(m) if weights is None else np.asarray(weights, float)
    ok = ~(np.isnan(m) | np.isnan(iv) | np.isnan(w))
    m, iv, w = m[ok], iv[ok], w[ok]
    if len(m) < 3:
        raise ValueError("need at least three quotes")
    X = np.column_stack([np.ones_like(m), m, m * m]) * np.sqrt(w)[:, None]
    coef = np.linalg.lstsq(X, iv * np.sqrt(w), rcond=None)[0]
    return tuple(round(float(c), 4) for c in coef)

def atm_term_structure(clean, S, r, q):
    rows = []
    for T in sorted(clean["T"].unique()):
        qT = q[T] if isinstance(q, dict) else q
        s = smile(clean, T, S, r, qT).dropna().sort_values("m")
        rows.append([T, float(np.interp(0.0, s["m"], s["iv"]))])
    return pd.DataFrame(rows, columns=["T", "atm_iv"])

def forward_vol(s1, T1, s2, T2):
    w = s2 ** 2 * T2 - s1 ** 2 * T1
    if w < 0:
        raise ValueError("total variance falls: calendar arbitrage")
    return sqrt(w / (T2 - T1))

def iv_surface(clean, S, r, q):
    out = {}
    for T in sorted(clean["T"].unique()):
        qT = q[T] if isinstance(q, dict) else q
        s = smile(clean, T, S, r, qT)
        out[float(T)] = fit_smile(s["m"], s["iv"])
    return out

def smile_iv(coeffs, m):
    a, b, c = coeffs
    return a + b * m + c * m * m

def interp_iv(surface, K, T, F_of_T):
    Ts = sorted(surface)
    def w_at(Tn):
        m = log(K / F_of_T(Tn)) / sqrt(Tn)
        return smile_iv(surface[Tn], m) ** 2 * Tn
    if T <= Ts[0]:
        m = log(K / F_of_T(T)) / sqrt(T)
        return smile_iv(surface[Ts[0]], m), T < Ts[0]
    if T >= Ts[-1]:
        m = log(K / F_of_T(T)) / sqrt(T)
        return smile_iv(surface[Ts[-1]], m), T > Ts[-1]
    for T1, T2 in zip(Ts, Ts[1:]):
        if T1 <= T <= T2:
            k = log(K / F_of_T(T))
            w1 = smile_iv(surface[T1], k / sqrt(T1)) ** 2 * T1
            w2 = smile_iv(surface[T2], k / sqrt(T2)) ** 2 * T2
            w = w1 + (w2 - w1) * (T - T1) / (T2 - T1)
            return sqrt(w / T), False

def norm_pdf(z):
    return exp(-z * z / 2) / sqrt(2 * pi)

def bs_greeks(S, K, r, sigma, T, kind="call", q=0.0):
    if T <= 0 or sigma <= 0:
        return {k: float("nan") for k in ("delta", "gamma", "vega", "theta", "rho")}
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    Sq, Kr = S * exp(-q * T), K * exp(-r * T)
    gamma = exp(-q * T) * norm_pdf(d1) / (S * sigma * sqrt(T))
    vega = Sq * norm_pdf(d1) * sqrt(T)
    decay = -Sq * norm_pdf(d1) * sigma / (2 * sqrt(T))
    if kind == "call":
        delta = exp(-q * T) * norm_cdf(d1)
        theta = decay - r * Kr * norm_cdf(d2) + q * Sq * norm_cdf(d1)
        rho = K * T * exp(-r * T) * norm_cdf(d2)
    elif kind == "put":
        delta = -exp(-q * T) * norm_cdf(-d1)
        theta = decay + r * Kr * norm_cdf(-d2) - q * Sq * norm_cdf(-d1)
        rho = -K * T * exp(-r * T) * norm_cdf(-d2)
    else:
        raise ValueError("kind must be 'call' or 'put'")
    return {"delta": delta, "gamma": gamma, "vega": vega, "theta": theta, "rho": rho}

def fd_greeks(pricer, S, sigma, T, h_S=0.01, h_sigma=0.0001, h_T=1 / 365):
    v = pricer(S, sigma, T)
    up, down = pricer(S + h_S, sigma, T), pricer(S - h_S, sigma, T)
    return {"delta": (up - down) / (2 * h_S),
            "gamma": (up - 2 * v + down) / h_S ** 2,
            "vega": (pricer(S, sigma + h_sigma, T) - pricer(S, sigma - h_sigma, T)) / (2 * h_sigma),
            "theta": -(pricer(S, sigma, T + h_T) - pricer(S, sigma, T - h_T)) / (2 * h_T)}

def best_bump(pricer, S, sigma, T, hs, true_gamma):
    errs = [abs(fd_greeks(pricer, S, sigma, T, h_S=h)["gamma"] - true_gamma) for h in hs]
    return hs[errs.index(min(errs))]

def greek_profile(name, strikes, T, S=100.0, r=0.05, sigma=0.2, q=0.0, kind="call"):
    return np.array([bs_greeks(S, K, r, sigma, T, kind, q)[name] for K in strikes])

def pnl_explain(greeks, dS, dsigma, dt):
    terms = {"delta": greeks["delta"] * dS,
             "gamma": 0.5 * greeks["gamma"] * dS ** 2,
             "vega": greeks["vega"] * dsigma,
             "theta": greeks["theta"] * dt}
    terms["total"] = sum(terms.values())
    return terms

def explain_vs_reval(S, K, r, sigma, T, dS, dsigma, dt, kind="call", q=0.0):
    g = bs_greeks(S, K, r, sigma, T, kind, q)
    explained = pnl_explain(g, dS, dsigma, dt)["total"]
    actual = bs_price(S + dS, K, r, sigma + dsigma, T - dt, kind, q) - bs_price(S, K, r, sigma, T, kind, q)
    return round(explained, 4), round(actual, 4), round(actual - explained, 4)

def vertical_violations(calls, disc=1.0):
    c = calls.sort_values("strike")
    K, C = list(c["strike"]), list(c["price"])
    out = []
    for i in range(1, len(K)):
        fall = C[i - 1] - C[i]
        if fall < 0:
            out.append((K[i], -fall))
        elif fall > disc * (K[i] - K[i - 1]):
            out.append((K[i], fall - disc * (K[i] - K[i - 1])))
    return out

def butterfly_violations(calls):
    c = calls.sort_values("strike")
    K, C = list(c["strike"]), list(c["price"])
    out = []
    for i in range(1, len(K) - 1):
        w = (K[i + 1] - K[i]) / (K[i + 1] - K[i - 1])
        fly = 2 * (w * C[i - 1] + (1 - w) * C[i + 1] - C[i])
        if fly < 0:
            out.append((K[i], -fly))
    return out

def node_iv(surface, K, T, F_of_T):
    return smile_iv(surface[T], log(K / F_of_T(T)) / sqrt(T))

def calendar_violations(surface, F_of_T, ks):
    Ts = sorted(surface)
    out = []
    for k in ks:
        w = [node_iv(surface, F_of_T(T) * exp(k), T, F_of_T) ** 2 * T for T in Ts]
        for i in range(len(Ts) - 1):
            if w[i + 1] < w[i]:
                out.append((k, Ts[i], Ts[i + 1]))
    return out

